","extract_layout.py":"from google.cloud import vision
from document_client import get_vision_client
from document_models import DocumentLayoutRequest, LayoutElement, LayoutResponse, bbox_to_dict


def extract_layout(request: DocumentLayoutRequest) -> LayoutResponse:
    client = get_vision_client()
    image = vision.Image(content=request.image_bytes)
    response = client.document_text_detection(image=image)
    elements = []
    page = response.full_text_annotation.pages[0] if response.full_text_annotation.pages else None
    if page:
        for block in page.blocks:
            elements.append(LayoutElement(kind="block", text=" ".join(s.text for p in block.paragraphs for s in p.words), bbox=bbox_to_dict(block.bounding_box)))
            for paragraph in block.paragraphs:
                line_text = " ".join(s.text for w in paragraph.words for s in w.symbols)
                elements.append(LayoutElement(kind="line", text=line_text, bbox=bbox_to_dict(paragraph.bounding_box)))
    return LayoutResponse(elements=elements, raw=response)
","extract_tables.py":"from google.cloud import documentai
from document_client import get_document_ai_client, get_document_ai_processor_name
from document_models import DocumentTableRequest, TableCell, TableRow, TableResponse, bbox_to_dict


def extract_tables(request: DocumentTableRequest) -> TableResponse:
    client = get_document_ai_client()
    name = get_document_ai_processor_name(request.processor_id, request.location, request.project_id)
    raw_document = documentai.RawDocument(content=request.image_bytes, mime_type=request.mime_type)
    doc = client.process_document(name=name, raw_document=raw_document)
    rows = []
    for page in doc.document.pages:
        for table in page.tables:
            for row in table.body_rows:
                cells = []
                for cell in row.cells:
                    cells.append(TableCell(text=cell.layout.text_anchor.content if cell.layout.text_anchor else "", bbox=bbox_to_dict(cell.layout.bounding_poly)))
                rows.append(TableRow(cells=cells))
    return TableResponse(rows=rows, raw=doc)
