def normalize_text(text: str) -> str:
    return " ".join(text.split()).strip()


def bbox_to_dict(bbox: Any) -> dict:
    if bbox is None:
        return {}
    vertices = getattr(bbox, "vertices", None) or []
    return {"vertices": [{"x": getattr(v, "x", None), "y": getattr(v, "y", None)} for v in vertices]}
